css:
.mc-sim-container {
    padding: 24px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: 'Courier New', 'SF Mono', 'Fira Code', monospace;
    color: #c9d1d9;
    line-height: 1.6;
}

.mc-sim-header {
    display: flex;
    align-items: center;
    gap: 20px;
    padding: 28px 32px;
    margin-bottom: 24px;
    background: linear-gradient(135deg, rgba(0,191,255,0.06) 0%, rgba(0,255,136,0.04) 100%);
    border: 1px solid rgba(0,191,255,0.2);
    border-left: 4px solid #00bfff;
    border-radius: 8px;
}

.mc-sim-header-badge {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 56px;
    height: 56px;
    background: linear-gradient(135deg, #00bfff, #00ff88);
    border-radius: 12px;
    font-size: 1.1rem;
    font-weight: 800;
    color: #0a0f1e;
    letter-spacing: 0.05em;
    flex-shrink: 0;
}

.mc-sim-header h1 {
    color: #00bfff;
    font-size: 1.5rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    margin: 0 0 4px 0;
    font-weight: 700;
}

.mc-sim-subtitle {
    color: #6b7b8d;
    font-size: 0.8rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin: 0;
}

.mc-sim-round-bar {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 12px 20px;
    margin-bottom: 24px;
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 6px;
    font-size: 0.85rem;
    color: #8b949e;
}

.mc-sim-round-bar span:nth-child(2) {
    color: #00ff88;
    font-weight: 700;
    font-size: 1.1rem;
}

.mc-sim-round-name {
    margin-left: auto;
    color: #00bfff;
    font-weight: 600;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}

.mc-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 24px;
}

.mc-sim-kpi-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px 16px;
    text-align: center;
    position: relative;
    overflow: hidden;
    transition: border-color 0.25s ease;
}

.mc-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #00bfff, #00ff88);
    opacity: 0.6;
}

.mc-sim-kpi-card:hover {
    border-color: #2d4a5e;
}

.mc-kpi-npv::before { background: #00ff88; }
.mc-kpi-risk::before { background: #ff6b6b; }
.mc-kpi-var::before { background: #ffa500; }
.mc-kpi-score::before { background: #00bfff; }

.mc-sim-kpi-icon {
    font-size: 0.6rem;
    font-weight: 800;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: #3d5a6e;
    margin-bottom: 8px;
}

.mc-sim-kpi-label {
    color: #6b7b8d;
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 8px;
}

.mc-sim-kpi-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #e6edf3;
    transition: color 0.3s ease;
}

.mc-kpi-npv .mc-sim-kpi-value { color: #00ff88; }
.mc-kpi-risk .mc-sim-kpi-value { color: #ff6b6b; }
.mc-kpi-var .mc-sim-kpi-value { color: #ffa500; }
.mc-kpi-score .mc-sim-kpi-value { color: #00bfff; }

.mc-sim-briefing {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 24px;
}

.mc-sim-briefing-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 16px;
}

.mc-sim-briefing-dot {
    width: 10px;
    height: 10px;
    background: #00ff88;
    border-radius: 50%;
    box-shadow: 0 0 8px rgba(0,255,136,0.5);
    animation: mc-pulse 2s ease-in-out infinite;
}

@keyframes mc-pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.4; }
}

.mc-sim-briefing-header h3 {
    color: #e6edf3;
    font-size: 1rem;
    font-weight: 700;
    margin: 0;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

.mc-sim-briefing-body {
    color: #8b949e;
    font-size: 0.85rem;
    line-height: 1.7;
}

.mc-sim-controls {
    background: #0d1520;
    border: 1px solid #1a2a3a;
    border-radius: 8px;
    padding: 28px;
    margin-bottom: 24px;
}

.mc-sim-controls h4 {
    color: #00bfff;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 0 0 24px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #1a2a3a;
}

.mc-sim-var-section {
    margin-bottom: 24px;
}

.mc-sim-var-section:last-child {
    margin-bottom: 0;
}

.mc-sim-var-section h5,
.mc-sim-controls h5 {
    color: #c9d1d9;
    font-size: 0.78rem;
    font-weight: 600;
    margin: 0 0 14px 0;
    letter-spacing: 0.04em;
}

.mc-sim-input-row {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
}

.mc-sim-input-group {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.mc-sim-input-group label {
    color: #6b7b8d;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}

.mc-sim-input-group input[type='number'],
.mc-sim-input-group select {
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #e6edf3;
    border-radius: 6px;
    padding: 10px 14px;
    font-family: 'Courier New', monospace;
    font-size: 0.9rem;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    width: 100%;
    box-sizing: border-box;
}

.mc-sim-input-group input:focus,
.mc-sim-input-group select:focus {
    outline: none;
    border-color: #00bfff;
    box-shadow: 0 0 8px rgba(0,191,255,0.2);
}

.mc-sim-wide {
    grid-column: 1 / -1;
}

.mc-sim-wide select {
    width: 100%;
    max-width: 400px;
}

.mc-sim-prob-total {
    margin-top: 12px;
    font-size: 0.78rem;
    color: #8b949e;
    padding: 8px 14px;
    background: rgba(0,191,255,0.05);
    border-radius: 4px;
}

.mc-sim-info-box {
    margin-top: 16px;
    padding: 16px 20px;
    background: rgba(0,255,136,0.05);
    border: 1px solid rgba(0,255,136,0.15);
    border-radius: 6px;
    color: #8b949e;
    font-size: 0.82rem;
}

.mc-sim-budget-bar {
    margin-top: 12px;
    padding: 10px 16px;
    background: rgba(0,191,255,0.05);
    border-radius: 4px;
    font-size: 0.78rem;
    color: #8b949e;
}

.mc-sim-option-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
}

.mc-sim-option-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px;
    transition: border-color 0.2s ease, background 0.2s ease;
}

.mc-sim-option-card:hover {
    border-color: #2d4a5e;
    background: #131d2e;
}

.mc-sim-check-label {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    cursor: pointer;
    margin-bottom: 10px;
}

.mc-sim-check-label input[type='checkbox'] {
    margin-top: 3px;
    accent-color: #00ff88;
    width: 16px;
    height: 16px;
    flex-shrink: 0;
}

.mc-sim-check-text {
    color: #e6edf3;
    font-size: 0.85rem;
    font-weight: 600;
}

.mc-sim-option-detail {
    color: #6b7b8d;
    font-size: 0.72rem;
    line-height: 1.5;
    padding-left: 26px;
}

.mc-sim-mitigation-preview {
    margin-top: 20px;
    padding: 16px 20px;
    background: rgba(0,255,136,0.05);
    border: 1px solid rgba(0,255,136,0.15);
    border-radius: 6px;
    font-size: 0.82rem;
    color: #c9d1d9;
    min-height: 40px;
}

.mc-sim-charts-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 24px;
}

.mc-sim-chart-box {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px;
    min-height: 280px;
    position: relative;
}

.mc-sim-history-section {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px;
    margin-bottom: 24px;
    overflow-x: auto;
}

.mc-sim-container .table {
    color: #c9d1d9;
    font-size: 0.78rem;
    margin: 0;
}

.mc-sim-container .table thead th {
    color: #00bfff;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border-bottom: 2px solid #1f2d3d;
    border-top: none;
    padding: 10px 12px;
}

.mc-sim-container .table td {
    border-color: #1a2232;
    padding: 8px 12px;
    vertical-align: middle;
}

.mc-sim-container .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(0,191,255,0.03);
}

.mc-sim-actions {
    display: flex;
    gap: 16px;
    align-items: center;
}

.mc-sim-submit-btn {
    background: linear-gradient(135deg, #00bfff, #0099cc);
    color: #0a0f1e;
    border: none;
    padding: 14px 36px;
    border-radius: 8px;
    font-family: 'Courier New', monospace;
    font-size: 0.9rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    cursor: pointer;
    transition: transform 0.15s ease, box-shadow 0.2s ease;
}

.mc-sim-submit-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(0,191,255,0.3);
}

.mc-sim-undo-btn {
    background: transparent;
    color: #6b7b8d;
    border: 1px solid #2d3f55;
    padding: 10px 24px;
    border-radius: 6px;
    font-family: 'Courier New', monospace;
    font-size: 0.78rem;
    cursor: pointer;
    transition: color 0.2s ease, border-color 0.2s ease;
}

.mc-sim-undo-btn:hover {
    color: #c9d1d9;
    border-color: #4a6a8a;
}

@media (max-width: 768px) {
    .mc-sim-container { padding: 16px; }
    .mc-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .mc-sim-input-row { grid-template-columns: 1fr; }
    .mc-sim-option-grid { grid-template-columns: 1fr; }
    .mc-sim-charts-row { grid-template-columns: 1fr; }
    .mc-sim-header { flex-direction: column; text-align: center; }
    .mc-sim-header h1 { font-size: 1.1rem; }
}

@media (max-width: 480px) {
    .mc-sim-kpi-grid { grid-template-columns: 1fr 1fr; gap: 10px; }
    .mc-sim-kpi-value { font-size: 1.2rem; }
}

/* --- completion message (v1.1.0) --- */
.mc-sim-cm { text-align:center; }
.mc-sim-cm-score { font-size:3rem; font-weight:700; color:#4fa3d7; line-height:1; }
.mc-sim-cm-max { font-size:1.1rem; color:#8899aa; }
.mc-sim-cm-verdict { font-size:1rem; text-transform:uppercase; letter-spacing:0.08em; color:#2ecc71; margin:8px 0 14px; font-weight:700; }
.mc-sim-cm-debrief { font-size:0.82rem; line-height:1.6; margin-bottom:16px; opacity:0.85; }
.mc-sim-cm-kpis { display:grid; grid-template-columns:repeat(3,1fr); gap:10px; margin-bottom:16px; }
.mc-sim-cm-kpi { border:1px solid rgba(120,140,170,0.3); border-radius:6px; padding:10px; display:flex; flex-direction:column; gap:4px; }
.mc-sim-cm-kpi span { font-size:0.58rem; text-transform:uppercase; letter-spacing:0.08em; opacity:0.7; }
.mc-sim-cm-kpi b { font-size:1rem; }
.mc-sim-cm-insights { text-align:left; font-size:0.8rem; line-height:1.6; padding-left:18px; margin:0; opacity:0.9; }
.mc-sim-cm-insights li { margin-bottom:6px; }

