            if (pct >= 60) return 'senior';
            if (pct >= 40) return 'junior';
            return 'beginner';
        }

        _grade(pct) {
            if (pct >= 80) return 'A';
            if (pct >= 60) return 'B';
            if (pct >= 40) return 'C';
            return 'D';
        }

        _cl(key, fallback) {
            var t = window.mySimulation ? window.mySimulation.t(key) : key;
            return (t && t !== key) ? t : fallback;
        }

        /* round name in the current language, looked up at render time; ROUND_NAMES stays the stored English value */
        _roundName(idx) {
            return this._cl('round_name_' + (idx + 1), this.ROUND_NAMES[idx] || '');
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cfMin: 40, cfMode: 65, cfMax: 85,
                    capexMin: 42.75, capexMode: 45, capexMax: 60.75,
                    tariffProbBase: 85, tariffProbPartial: 10, tariffProbSpot: 5,
                    iterations: 10000, confidence: 95,
                    npvMean: 12.4, npvMedian: 0, npvStdDev: 0,
                    probNegative: 0, varValue: 0,
                    npvDistData: [], npvDistLabels: [],
                    tornadoLabels: [], tornadoRanges: [],
                    tornadoLow: [], tornadoHigh: [],
                    dominantRisk: 0,
                    budgetCF: 0, budgetCapex: 0, budgetTariff: 0,
                    optLeverage: false, optInsurance: false,
                    optEPC: false, optPPA: false,
                    postNpvMean: 0, postProbNeg: 0, postStdDev: 0,
                    totalScore: 0, scoreHistory: [],
                    performance: { overallScore: 0, grade: 'D', tier: 'beginner' }
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    cfMin: 40, cfMode: 65, cfMax: 85,
                    capexMin: 42.75, capexMode: 45, capexMax: 60.75,
                    tariffProbBase: 85, tariffProbPartial: 10, tariffProbSpot: 5,
                    iterations: 10000, confidence: 95,
                    dominantRisk: 0,
                    budgetCF: 0, budgetCapex: 0, budgetTariff: 0,
                    optLeverage: false, optInsurance: false,
                    optEPC: false, optPPA: false
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var round = state.currentPeriod;

            if (round === 1) {
                var cfMin = document.getElementById('cfMin');
                var cfMode = document.getElementById('cfMode');
                var cfMax = document.getElementById('cfMax');
                var capexMin = document.getElementById('capexMin');
                var capexMode = document.getElementById('capexMode');
                var capexMax = document.getElementById('capexMax');
                var tpBase = document.getElementById('tariffProbBase');
                var tpPartial = document.getElementById('tariffProbPartial');
                var tpSpot = document.getElementById('tariffProbSpot');

                if (cfMin) decisions.cfMin = parseFloat(cfMin.value);
                if (cfMode) decisions.cfMode = parseFloat(cfMode.value);
                if (cfMax) decisions.cfMax = parseFloat(cfMax.value);
                if (capexMin) decisions.capexMin = parseFloat(capexMin.value);
                if (capexMode) decisions.capexMode = parseFloat(capexMode.value);
                if (capexMax) decisions.capexMax = parseFloat(capexMax.value);
                if (tpBase) decisions.tariffProbBase = parseFloat(tpBase.value);
                if (tpPartial) decisions.tariffProbPartial = parseFloat(tpPartial.value);
                if (tpSpot) decisions.tariffProbSpot = parseFloat(tpSpot.value);

                if (decisions.cfMin >= decisions.cfMode || decisions.cfMode >= decisions.cfMax) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_cf_order'), 'warning');
                    return false;
                }
                if (decisions.capexMin >= decisions.capexMode || decisions.capexMode >= decisions.capexMax) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_capex_order'), 'warning');
                    return false;
                }
                var probSum = decisions.tariffProbBase + decisions.tariffProbPartial + decisions.tariffProbSpot;
                if (Math.abs(probSum - 100) > 1) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_prob_sum'), 'warning');
                    return false;
                }
            }
            else if (round === 2) {
                var iterSel = document.getElementById('iterationsSelect');
                var confSel = document.getElementById('confidenceSelect');
                if (iterSel) decisions.iterations = parseInt(iterSel.value);
                if (confSel) decisions.confidence = parseInt(confSel.value);
            }
            else if (round === 3) {
                var domRisk = document.getElementById('dominantRiskSelect');
                var bCF = document.getElementById('budgetCF');
                var bCap = document.getElementById('budgetCapex');
                var bTar = document.getElementById('budgetTariff');
                if (domRisk) decisions.dominantRisk = parseInt(domRisk.value);
                if (bCF) decisions.budgetCF = parseFloat(bCF.value) || 0;
                if (bCap) decisions.budgetCapex = parseFloat(bCap.value) || 0;
                if (bTar) decisions.budgetTariff = parseFloat(bTar.value) || 0;

                if (decisions.dominantRisk === 0) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_select_risk'), 'warning');
                    return false;
                }
                var totalBudget = decisions.budgetCF + decisions.budgetCapex + decisions.budgetTariff;
                if (totalBudget > 10.5) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_over_budget'), 'warning');
                    return false;
                }
            }
            else if (round === 4) {
                var oL = document.getElementById('optLeverage');
                var oI = document.getElementById('optInsurance');
                var oE = document.getElementById('optEPC');
                var oP = document.getElementById('optPPA');
                if (oL) decisions.optLeverage = oL.checked;
                if (oI) decisions.optInsurance = oI.checked;
                if (oE) decisions.optEPC = oE.checked;
                if (oP) decisions.optPPA = oP.checked;
            }

            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            var round = state.currentPeriod;
            var results;

            if (round === 1) results = this._processRound1(state);
            else if (round === 2) results = this._processRound2(state);
            else if (round === 3) results = this._processRound3(state);
            else results = this._processRound4(state);

            // --- GRADING CONTRACT: server reads domainState.performance.overallScore ---
            var composite = this._composite(state.domainState);
            if (!state.domainState.performance) state.domainState.performance = {};
            state.domainState.performance.overallScore = composite;
            state.domainState.performance.grade = this._grade(composite);
            state.domainState.performance.tier = this._tier(composite);
            state.domainState.performanceTier = this._tier(composite);
            if (results) results.overallScore = composite;

            var self = this;
            if (state.currentPeriod < state.maxPeriods) {
                setTimeout(((__eqilNext) => function() {
                    self._updateBriefing({ currentPeriod: __eqilNext, domainState: state.domainState });
                })(state.currentPeriod + 1), 500);
            }

            return results;
        }

        _processRound1(state) {
            var d = state.decisions;
            var ds = state.domainState;

            ds.cfMin = d.cfMin;
            ds.cfMode = d.cfMode;
            ds.cfMax = d.cfMax;
            ds.capexMin = d.capexMin;
            ds.capexMode = d.capexMode;
            ds.capexMax = d.capexMax;
            ds.tariffProbBase = d.tariffProbBase;
            ds.tariffProbPartial = d.tariffProbPartial;
            ds.tariffProbSpot = d.tariffProbSpot;

            var score = 100;
            score -= Math.min(30, Math.abs(d.cfMin - 40) * 2);
            score -= Math.min(20, Math.abs(d.cfMode - 65) * 2);
            score -= Math.min(20, Math.abs(d.cfMax - 85) * 2);
            score -= Math.min(10, Math.abs(d.capexMin - 42.75) * 2);
            score -= Math.min(10, Math.abs(d.capexMax - 60.75) * 1);
            var probSum = d.tariffProbBase + d.tariffProbPartial + d.tariffProbSpot;
            if (Math.abs(probSum - 100) > 1) score -= 15;
            score -= Math.min(10, Math.abs(d.tariffProbBase - 85) * 0.5);
            score = Math.max(0, Math.min(100, Math.round(score)));

            ds.totalScore += score;
            ds.scoreHistory.push(score);

            return {
                period: state.currentPeriod,
                roundName: this.ROUND_NAMES[0],
                cfRange: d.cfMin + '% - ' + d.cfMax + '%',
                capexRange: '$' + d.capexMin + 'M - $' + d.capexMax + 'M',
                score: score,
                totalScore: ds.totalScore
            };
        }

        _processRound2(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var iterations = d.iterations;
            var confidence = d.confidence;
            ds.iterations = iterations;
            ds.confidence = confidence;

            var npvResults = [];
            var i, cf, capex, tariff, opex, duration, npv;

            for (i = 0; i < iterations; i++) {
                cf = this._sampleTriangular(ds.cfMin, ds.cfMode, ds.cfMax);
                capex = this._sampleTriangular(ds.capexMin, ds.capexMode, ds.capexMax);
                tariff = this._sampleTariff(ds.tariffProbBase, ds.tariffProbPartial, ds.tariffProbSpot);
                opex = this._sampleNormalTrunc(1.2, 0.15, 0.96, 1.44);
                duration = this._sampleNormalTrunc(24, 2, 20, 30);
                npv = this._calcNPV(cf, capex, tariff, opex, duration);
                npvResults.push(npv);
            }

            npvResults.sort(function(a, b) { return a - b; });

            var sum = 0;
            var negCount = 0;
            for (i = 0; i < npvResults.length; i++) {
                sum += npvResults[i];
                if (npvResults[i] < 0) negCount++;
            }
            var mean = sum / npvResults.length;
            var median = npvResults[Math.floor(npvResults.length / 2)];
            var variance = 0;
            for (i = 0; i < npvResults.length; i++) {
                variance += (npvResults[i] - mean) * (npvResults[i] - mean);
            }
            var stdDev = Math.sqrt(variance / npvResults.length);
            var probNeg = (negCount / npvResults.length) * 100;
            var varIdx = Math.floor(npvResults.length * (1 - confidence / 100));
            var varVal = npvResults[Math.max(0, varIdx)];

            var minNPV = npvResults[0];
            var maxNPV = npvResults[npvResults.length - 1];
            var binCount = 25;
            var binWidth = (maxNPV - minNPV) / binCount;
            var bins = [];
            var binLabels = [];
            for (i = 0; i < binCount; i++) {
                bins.push(0);
                binLabels.push(Math.round((minNPV + i * binWidth) * 10) / 10);
            }
            for (i = 0; i < npvResults.length; i++) {
                var b = Math.floor((npvResults[i] - minNPV) / binWidth);
                if (b >= binCount) b = binCount - 1;
                if (b < 0) b = 0;
                bins[b]++;
            }

            ds.npvMean = Math.round(mean * 100) / 100;
            ds.npvMedian = Math.round(median * 100) / 100;
            ds.npvStdDev = Math.round(stdDev * 100) / 100;
            ds.probNegative = Math.round(probNeg * 10) / 10;
            ds.varValue = Math.round(varVal * 100) / 100;
            ds.npvDistData = bins;
            ds.npvDistLabels = binLabels.map(function(v) { return '$' + v.toFixed(1) + 'M'; });

            var score = 50;
            if (iterations >= 10000) score += 25;
            else if (iterations >= 5000) score += 15;
            else score += 5;
            if (confidence === 95) score += 25;
            else if (confidence === 99) score += 20;
            else score += 15;
            score = Math.max(0, Math.min(100, Math.round(score)));

            ds.totalScore += score;
            ds.scoreHistory.push(score);

            return {
                period: state.currentPeriod,
                roundName: this.ROUND_NAMES[1],
                iterations: iterations,
                npvMean: '$' + ds.npvMean.toFixed(1) + 'M',
                probNeg: ds.probNegative.toFixed(1) + '%',
                varValue: '$' + ds.varValue.toFixed(1) + 'M',
                score: score,
                totalScore: ds.totalScore
            };
        }

        _processRound3(state) {
            var d = state.decisions;
            var ds = state.domainState;

            var baseNPV = this._calcNPV(ds.cfMode, ds.capexMode, 95, 1.2, 24);

            var cfP5 = this._triangularPctl(ds.cfMin, ds.cfMode, ds.cfMax, 0.05);
            var cfP95 = this._triangularPctl(ds.cfMin, ds.cfMode, ds.cfMax, 0.95);
            var capP5 = this._triangularPctl(ds.capexMin, ds.capexMode, ds.capexMax, 0.05);
            var capP95 = this._triangularPctl(ds.capexMin, ds.capexMode, ds.capexMax, 0.95);

            var ranges = [
                { label: 'Capacity Factor', low: this._calcNPV(cfP5, ds.capexMode, 95, 1.2, 24), high: this._calcNPV(cfP95, ds.capexMode, 95, 1.2, 24) },
                { label: 'Capex', low: this._calcNPV(ds.cfMode, capP95, 95, 1.2, 24), high: this._calcNPV(ds.cfMode, capP5, 95, 1.2, 24) },
                { label: 'Tariff', low: this._calcNPV(ds.cfMode, ds.capexMode, 65, 1.2, 24), high: this._calcNPV(ds.cfMode, ds.capexMode, 95, 1.2, 24) },
                { label: 'Opex', low: this._calcNPV(ds.cfMode, ds.capexMode, 95, 1.44, 24), high: this._calcNPV(ds.cfMode, ds.capexMode, 95, 0.96, 24) },
                { label: 'Duration', low: this._calcNPV(ds.cfMode, ds.capexMode, 95, 1.2, 30), high: this._calcNPV(ds.cfMode, ds.capexMode, 95, 1.2, 20) }
            ];

            for (var i = 0; i < ranges.length; i++) {
                ranges[i].range = Math.abs(ranges[i].high - ranges[i].low);
            }
            ranges.sort(function(a, b) { return b.range - a.range; });

            ds.tornadoLabels = ranges.map(function(r) { return r.label; });
            ds.tornadoRanges = ranges.map(function(r) { return Math.round(r.range * 100) / 100; });
            ds.tornadoLow = ranges.map(function(r) { return Math.round(r.low * 100) / 100; });
            ds.tornadoHigh = ranges.map(function(r) { return Math.round(r.high * 100) / 100; });

            var score = 0;
            if (d.dominantRisk === 1) score += 50;
            else if (d.dominantRisk === 2) score += 20;
            else if (d.dominantRisk === 3) score += 10;
            else score += 0;

            var totalBudget = d.budgetCF + d.budgetCapex + d.budgetTariff;
            if (totalBudget > 0 && totalBudget <= 10) {
                if (d.budgetCF >= d.budgetCapex && d.budgetCF >= d.budgetTariff) {
                    score += 30;
                } else if (d.budgetCapex >= d.budgetCF && d.budgetCapex >= d.budgetTariff) {
                    score += 15;
                } else {
                    score += 5;
                }
                if (d.budgetCF > 0 && d.budgetCapex > 0) score += 10;
                if (totalBudget >= 8) score += 10;
            }
            score = Math.max(0, Math.min(100, Math.round(score)));

            ds.dominantRisk = d.dominantRisk;
            ds.budgetCF = d.budgetCF;
            ds.budgetCapex = d.budgetCapex;
            ds.budgetTariff = d.budgetTariff;
            ds.totalScore += score;
            ds.scoreHistory.push(score);

            return {
                period: state.currentPeriod,
                roundName: this.ROUND_NAMES[2],
                topRisk: ranges[0].label,
                topRange: '$' + ranges[0].range.toFixed(1) + 'M',
                riskChoice: d.dominantRisk === 1 ? 'Correct' : 'Incorrect',
                score: score,
                totalScore: ds.totalScore
            };
        }

        _processRound4(state) {
            var d = state.decisions;
            var ds = state.domainState;

            var npvCost = 0;
            var probReduce = 0;
            var stdReduce = 0;

            if (d.optLeverage) { npvCost += 3.7; probReduce += 4.3; stdReduce += 1.5; }
            if (d.optInsurance) { npvCost += 5.0; probReduce += 7.3; stdReduce += 2.0; }
            if (d.optEPC) { npvCost += 4.0; probReduce += 2.0; stdReduce += 1.0; }
            if (d.optPPA) { npvCost -= 0.6; probReduce += 3.3; stdReduce += 0.5; }

            var postNpv = ds.npvMean - npvCost;
            var postProb = Math.max(0, ds.probNegative - probReduce);
            var postStd = Math.max(1, ds.npvStdDev - stdReduce);

            ds.optLeverage = d.optLeverage;
            ds.optInsurance = d.optInsurance;
            ds.optEPC = d.optEPC;
            ds.optPPA = d.optPPA;
            ds.postNpvMean = Math.round(postNpv * 100) / 100;
            ds.postProbNeg = Math.round(postProb * 10) / 10;
            ds.postStdDev = Math.round(postStd * 100) / 100;

            var score = 0;
            if (postProb <= 5) score += 35;
            else if (postProb <= 8) score += 25;
            else if (postProb <= 10) score += 15;

            if (postNpv > 5) score += 25;
            else if (postNpv > 0) score += 15;
            else score -= 10;

            var count = 0;
            if (d.optLeverage) count++;
            if (d.optInsurance) count++;
            if (d.optEPC) count++;
            if (d.optPPA) count++;
            if (count >= 2 && count <= 3) score += 20;
            else if (count === 1) score += 10;
            else if (count === 4) score += 5;

            if (d.optLeverage && d.optEPC && d.optPPA && !d.optInsurance) score += 20;
            else if (d.optLeverage && d.optEPC) score += 10;

            score = Math.max(0, Math.min(100, Math.round(score)));
            ds.totalScore += score;
            ds.scoreHistory.push(score);

            ds.npvMean = postNpv;
            ds.probNegative = postProb;
            ds.npvStdDev = postStd;

            return {
                period: state.currentPeriod,
                roundName: this.ROUND_NAMES[3],
                postNpv: '$' + postNpv.toFixed(1) + 'M',
                postProb: postProb.toFixed(1) + '%',
                measures: count,
                score: score,
                totalScore: ds.totalScore
            };
        }

        _sampleTriangular(min, mode, max) {
            var u = Math.random();
            var fc = (mode - min) / (max - min);
            if (u < fc) {
                return min + Math.sqrt(u * (max - min) * (mode - min));
            }
            return max - Math.sqrt((1 - u) * (max - min) * (max - mode));
        }

        _sampleNormalTrunc(mean, std, lo, hi) {
            var val;
            do {
                var u1 = Math.random();
                var u2 = Math.random();
                var z = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
                val = mean + z * std;
            } while (val < lo || val > hi);
            return val;
        }

        _sampleTariff(probBase, probPartial, probSpot) {
            var r = Math.random() * 100;
            if (r < probBase) return 95;
            if (r < probBase + probPartial) return 85;
            return 65;
        }

        _triangularPctl(min, mode, max, p) {
            var fc = (mode - min) / (max - min);
            if (p <= fc) {
                return min + Math.sqrt(p * (max - min) * (mode - min));
            }
            return max - Math.sqrt((1 - p) * (max - min) * (max - mode));
        }

        _calcNPV(cf, capex, tariff, opex, duration) {
            var wacc = 0.082;
            var years = 15;
            var annualMWh = 15 * (cf / 100) * 8760;
            var extraMonths = Math.max(0, duration - 24);
            var idc = capex * 0.065 * (extraMonths / 12);
            var totalCapex = capex + idc;
            var npv = -totalCapex;
            for (var t = 1; t <= years; t++) {
                var yearTariff = tariff * Math.pow(1.02, t - 1);
                var revenue = annualMWh * yearTariff / 1000000;
                var depreciation = totalCapex / years;
                var taxable = revenue - opex - depreciation;
                var tax = taxable > 0 ? taxable * 0.22 : 0;
                var fcf = revenue - opex - tax;
                npv += fcf / Math.pow(1 + wacc, t);
            }
            return npv;
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, 3);
            var titles = [
                window.mySimulation ? window.mySimulation.t('r1_brief_title') : 'Round 1: Distribution Design',
                window.mySimulation ? window.mySimulation.t('r2_brief_title') : 'Round 2: Monte Carlo Simulation',
                window.mySimulation ? window.mySimulation.t('r3_brief_title') : 'Round 3: Sensitivity Analysis',
                window.mySimulation ? window.mySimulation.t('r4_brief_title') : 'Round 4: Risk Mitigation Decision'
            ];
            var bodies = [
                window.mySimulation ? window.mySimulation.t('r1_brief_body') : 'Define probability distributions for each uncertain variable. The hydroelectric project on the Tarcoles River faces uncertainty in rainfall (capacity factor), construction costs, electricity tariffs, operational costs, and construction duration.<br><br>Set the minimum, mode, and maximum for triangular distributions, and scenario probabilities for tariff risk.',
                window.mySimulation ? window.mySimulation.t('r2_brief_body') : 'Execute the Monte Carlo simulation using your distributions. The engine will generate thousands of random scenarios, calculate NPV for each, and produce a probability distribution of outcomes.<br><br>Choose the number of iterations and VaR confidence level.',
                window.mySimulation ? window.mySimulation.t('r3_brief_body') : 'The tornado chart shows which variable has the greatest impact on NPV. Identify the dominant risk and allocate your $10M mitigation budget proportionally to each risk factor.<br><br>Focus your resources where they have the most impact.',
                window.mySimulation ? window.mySimulation.t('r4_brief_body') : 'Based on your analysis, select a package of risk mitigation strategies. Each measure reduces risk but costs money.<br><br>The goal: reduce the probability of NPV < 0 to an acceptable level while preserving positive expected returns.'
            ];

            var titleEl = document.getElementById('briefingTitle');
            var bodyEl = document.getElementById('briefingText');
            if (titleEl) titleEl.innerHTML = titles[idx];
            if (bodyEl) bodyEl.innerHTML = bodies[idx];

            var nameEl = document.getElementById('roundNameDisplay');
            if (nameEl && this.ROUND_NAMES[idx]) nameEl.textContent = this._roundName(idx);

            for (var r = 1; r <= 4; r++) {
                var panel = document.getElementById('round' + r + 'Controls');
                if (panel) panel.style.display = (r === idx + 1) ? 'block' : 'none';
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('npvDisplay', 'domainState.npvMean', function(v) {
                if (typeof v === 'number') return '$' + v.toFixed(1) + 'M';
                return v;
            });
            uiManager.bind('probNegDisplay', 'domainState.probNegative', function(v) {
                if (v === 0 && !window.mySimulation.state.domainState.npvStdDev) return '\u2014';
                return v.toFixed(1) + '%';
            });
            uiManager.bind('varDisplay', 'domainState.varValue', function(v) {
                if (v === 0 && !window.mySimulation.state.domainState.npvStdDev) return '\u2014';
                return '$' + v.toFixed(1) + 'M';
            });
            uiManager.bind('scoreDisplay', 'domainState.totalScore');
        }

        getChartConfig() {
            return {
                npvChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'NPV Distribution (Frequency)',
                            data: [],
                            backgroundColor: 'rgba(0,191,255,0.5)',
                            borderColor: '#00bfff',
                            borderWidth: 1
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'NPV Probability Distribution', color: '#c9d1d9', font: { family: 'Courier New', size: 13 } },
                            legend: { display: false }
                        },
                        scales: {
                            x: {
                                ticks: { color: '#6b7b8d', maxRotation: 45, font: { size: 9 } },
                                grid: { color: 'rgba(31,45,61,0.5)' }
                            },
                            y: {
                                beginAtZero: true,
