        getChartData(state) {
            return {
                npvChart: {
                    labels: state.domainState.npvDistLabels || [],
                    datasets: [{ data: state.domainState.npvDistData || [] }]
                },
                sensitivityChart: {
                    labels: state.domainState.tornadoLabels || [],
                    datasets: [{ data: state.domainState.tornadoRanges || [] }]
                }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.roundName', label: 'Round', i18nKey: 'col_round', formatter: function(v) { var i = self.ROUND_NAMES.indexOf(v); return i >= 0 ? self._roundName(i) : v; } },
                { key: 'results.score', label: 'Score', i18nKey: 'col_score' },
                { key: 'results.totalScore', label: 'Cumulative', i18nKey: 'col_cumulative' }
            ];
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = (window.mySimulation && window.mySimulation.state) ? window.mySimulation.state.domainState : {};
            var scores = history.map(function(r) { return r.results ? r.results.score || 0 : 0; });
            var rawScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var maxPossible = 400;
            var pct = Math.round((rawScore / maxPossible) * 100);
            var tier = this._tier(pct);
            var T = function(k) { return window.mySimulation.t(k); };

            var insights = [];
            insights.push(scores[0] >= 80 ? T('insight_dist_strong') : T('insight_dist_weak'));
            if (scores.length >= 3) insights.push(scores[2] >= 70 ? T('insight_risk_strong') : T('insight_risk_weak'));
            if (scores.length >= 4) insights.push(scores[3] >= 70 ? T('insight_mit_strong') : T('insight_mit_weak'));

            return {
                overallScore: pct,
                score: pct,
                totalScore: pct,
                rawScore: rawScore,
                maxPossible: maxPossible,
                percentage: pct,
                npvMean: Math.round((ds.npvMean || 0) * 10) / 10,
                probNegative: Math.round(ds.probNegative || 0),
                performance: tier,
                performanceLabel: this._cl('grade_' + tier, tier),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var T = function(k) { return window.mySimulation.t(k); };
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var verdict = s.performanceLabel || s.performance || '';
            var kpis = ''
                + '<div class="mc-sim-cm-kpi"><span>' + T('cm_kpi_points') + '</span><b>' + (s.rawScore || 0) + '/400</b></div>'
                + '<div class="mc-sim-cm-kpi"><span>' + T('cm_kpi_npv') + '</span><b>$' + (s.npvMean || 0) + 'M</b></div>'
                + '<div class="mc-sim-cm-kpi"><span>' + T('cm_kpi_ploss') + '</span><b>' + (s.probNegative || 0) + '%</b></div>';
            var items = (s.insights || []).map(function(t) { return '<li>' + t + '</li>'; }).join('');
            return '<div class="mc-sim-cm">'
                + '<div class="mc-sim-cm-score">' + score + '<span class="mc-sim-cm-max">/100</span></div>'
                + '<div class="mc-sim-cm-verdict">' + verdict + '</div>'
                + '<div class="mc-sim-cm-debrief">' + T('cm_debrief') + '</div>'
                + '<div class="mc-sim-cm-kpis">' + kpis + '</div>'
                + '<ul class="mc-sim-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            var round = state.currentPeriod;
            if (round === 1) return window.mySimulation.t('hint_r1');
            if (round === 2 && state.domainState.probNegative > 15) return window.mySimulation.t('hint_r2_high_risk');
            if (round === 2) return window.mySimulation.t('hint_r2');
            if (round === 3) return window.mySimulation.t('hint_r3');
            if (round === 4 && state.domainState.postProbNeg <= 5) return window.mySimulation.t('hint_r4_good');
            if (round === 4) return window.mySimulation.t('hint_r4');
            return null;
        }

